import{z as m,x as d,o as i,c as A,q as s,j as n,D as t,d as o,s as l,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const y=JSON.parse('{"title":"最优商品税 Ramsey","description":"","frontmatter":{"title":"最优商品税 Ramsey","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ramsey-optimal-commodity-tax.md","filePath":"econ/ramsey-optimal-commodity-tax.md","lastUpdated":1791413859000}'),p={name:"econ/ramsey-optimal-commodity-tax.md"};function B(D,a,R,u,h,C){const r=d("Mermaid");return i(),A("div",null,[a[2]||(a[2]=s('<h1 id="最优商品税-ramsey" tabindex="-1">最优商品税 Ramsey <a class="header-anchor" href="#最优商品税-ramsey" aria-label="Permalink to &quot;最优商品税 Ramsey&quot;">​</a></h1><div class="epigraph"><p>一次总付不可用时，筹固定收入的商品税应使补偿需求大致等比例收缩；独立需求下这就是逆弹性。效率公式不是对穷人征税的许可证。</p><footer>—— Ramsey, A Contribution to the Theory of Taxation, Economic Journal 1927；Diamond and Mirrlees, AER 1971；对照 Atkinson and Stiglitz；主干课拉姆齐商品税</footer></div><p><a href="/econ/public-goods-free-rider">上一课</a>给出必须用公共预算提供 \\(G\\) 的理由。本课缺口是筹资楔子：总额税若不可用（能力不可观察、或政治约束），只能在商品上钉 \\(t\\)，如何分布损失最小。主干<a href="/econ/ramsey-commodity-tax">拉姆齐商品税</a>已写逆弹性。公共财政续课把它接到：公共品的 \\(R\\)、生产效率（中间品不征）、以及下一课所得税为何还要另开一刀。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代表性消费者，政府要 \\(\\sum t_i x_i\\ge R\\)。Ramsey：最优处各补偿需求下降比例相近；需求独立则 \\(t_i/(1+t_i)\\propto 1/\\varepsilon_i\\)。无弹性税基上税率更高，同样 \\(R\\) 造成的产量收缩更小，无谓损失的二次项更省。缺口是把这句话从教科书特解收回财政：上一课的 \\(G\\) 决定 \\(R\\) 的一部分；Diamond–Mirrlees：生产应保持有效，扭曲留在最终消费，中间品不征——否则公共生产与私人生产的边界被税搞乱。</p><p><span class="marginnote">术语翻译：「补偿需求」就是先把税造成的收入损失退给消费者、只留下纯价格效应之后的需求。Ramsey 规则钉它，因为收入效应原则上可用总额转移抵消，剩下真正造成扭曲的是替代。</span></p><p>交叉弹性在时，不能逐市场套 \\(1/\\varepsilon\\)。有闲暇且闲暇不能直接征税时，Corlett–Hague：对与闲暇互补的商品多征，等于间接税闲暇。</p><h3 id="逆弹性不是公平命令" tabindex="-1">逆弹性不是公平命令 <a class="header-anchor" href="#逆弹性不是公平命令" aria-label="Permalink to &quot;逆弹性不是公平命令&quot;">​</a></h3><p>必需品往往无弹性。效率特解会加重对它们的税，伤害穷人。Ramsey 原问题是代表性消费者；Diamond 1975 加上异质与福利权重后，公式多一项分配特征。本课先钉效率，下一课用所得税处理能力差异。把逆弹性写成「所以应该对粮食重税」，是把次优公式读成规范口号。</p><p><span class="marginnote">Atkinson–Stiglitz：若有非线性所得税且偏好对商品弱可分，商品税可能多余。续课要记住：Ramsey 公式的前提是「只能征商品税」；工具集一变，公式就变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规划：\\(\\max v(q)\\) s.t. \\((q-p)\\cdot x(q)\\ge R\\)。一阶条件给出 Ramsey 规则。公共品：把 \\(G\\) 与 \\(R\\) 联立，萨缪尔森条件在次优下要加扭曲的边际成本——提供 \\(G\\) 的边际公共资金不再是 1。自然垄断的 Ramsey 定价（主干另一课）是同一数学、不同故事：那里是覆盖固定成本的价，这里是覆盖财政 \\(R\\) 的税。</p><p><span class="marginnote">数字实例：若边际公共资金 \\(\\mathrm{MCF}=1.2\\)，一个每花 1 元产出 1.5 元社会评价的公共品仍该建（1.5 \\(\\gt\\) 1.2）；产出只有 1.1 元就该缓建。扭曲把「划算」的门槛从 1 元抬到了 1.2 元。</span></p>',13)),(i(),n(E,null,{default:t(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%85%AC%E5%85%B1%E5%93%81%E9%9C%80%E8%A6%81%20R%22%5D%20--%3E%20RAM%5B%22%E5%95%86%E5%93%81%E7%A8%8E%E6%A5%94%E5%AD%90%22%5D%0A%20%20RAM%20--%3E%20INV%5B%22%E9%80%86%E5%BC%B9%E6%80%A7%20%2F%20%E7%AD%89%E6%AF%94%E4%BE%8B%E6%94%B6%E7%BC%A9%22%5D%0A%20%20RAM%20--%3E%20DM%5B%22Diamond%E2%80%93Mirrlees%3A%20%E4%B8%AD%E9%97%B4%E5%93%81%E4%B8%8D%E5%BE%81%22%5D%0A%20%20INV%20--%3E%20INC%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E8%83%BD%E5%8A%9B%E5%B7%AE%E5%BC%82%E4%B8%8E%E6%89%80%E5%BE%97%E7%A8%8E%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要把关税当 Ramsey 商品税的应用就停：关税还有贸易条件与保护，对象是边境，不是同一套内部 \\(t\\)。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是在不可观察的一次总付约束下，用弹性分配扭曲。无谓损失随税率二次上升，应把楔子放在「数量不太动」的基上。交叉项把商品连成系统，单独看 \\(\\varepsilon_{ii}\\) 会误导——与 IO 里不能只看自价格弹性是同一几何。生产效率：对中间品征税会在厂商之间造成不同的边际转换，像无故破坏第一最佳生产，Diamond–Mirrlees 把它排除。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易把 Diamond–Mirrlees 的「生产效率」读成「要国有高效生产」。它说的是别对中间品征税、让所有厂商面对同一组相对价格，否则公共与私人生产的边界被税搞乱——讲的是税基，不是所有制。")],-1)),a[7]||(a[7]=e("p",null,"边际公共资金：多抽一元 \\(R\\) 的社会成本大于一元，因为扭曲。上一课的 \\(G\\) 应提供到 \\(\\sum\\mathrm{MRS}=\\) 被这个因子放大后的 MRT，而不是第一最佳的 \\(\\sum\\mathrm{MRS}=\\mathrm{MRT}\\)。",-1)),(i(),n(E,null,{default:t(()=>[l(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22%E5%A4%9A%E7%AD%B9%201%20%E5%85%83%20R%22%5D%20--%3E%20DIST%5B%22%E5%95%86%E5%93%81%E7%A8%8E%E6%89%AD%E6%9B%B2%2C%20%E9%80%A0%E6%88%90%E9%A2%9D%E5%A4%96%E4%B8%89%E8%A7%92%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20DIST%20--%3E%20MCF%5B%22%E8%BE%B9%E9%99%85%E5%85%AC%E5%85%B1%E8%B5%84%E9%87%91%20%3D%201%20%2B%20%E6%89%AD%E6%9B%B2%E6%88%90%E6%9C%AC%22%5D%0A%20%20MCF%20--%3E%20GCOND%5B%22%E5%85%AC%E5%85%B1%E5%93%81%E6%9D%A1%E4%BB%B6%3A%20%CE%A3MRS%20%3D%20MCF%20%C3%97%20MRT%22%5D%0A%20%20GCOND%20--%3E%20LOWER%5B%22MCF%20%E8%B6%8A%E5%A4%A7%2C%20G%20%E7%9A%84%E9%97%A8%E6%A7%9B%E8%B6%8A%E9%AB%98%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">Ramsey 1927 的原话是无穷小税使需求等比例减少。独立需求时才等于逆弹性口诀。写应用时先问交叉与闲暇。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把增值税税率表写成最优解，不重写次优定理的全部拉格朗日。所得税、非线性劳动楔子是下一课。量化栏没有「Ramsey 交易税」要在此对接。后课默认：筹 \\(R\\) 的商品税按 Ramsey–Diamond–Mirrlees 语言来读；分配目标另用所得税或福利权重修正，不把逆弹性当公平。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总额税不可用时，商品税按等比例收缩 / 逆弹性分配扭曲。</li><li>逆弹性是效率特解，不是对穷人征税的理由。</li><li>Diamond–Mirrlees：保持生产效率，中间品不征。</li><li>公共品的次优萨缪尔森条件含边际公共资金。</li><li>出处：Ramsey 1927；Diamond and Mirrlees 1971；Atkinson and Stiglitz。</li></ul>',5))])}const f=m(p,[["render",B]]);export{y as __pageData,f as default};
